async (page) => {
  const out = '/private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin/e017b21e-f4da-471a-9b19-14e9148b503c/scratchpad/fixture/shots';
  await page.setViewportSize({ width: 1200, height: 800 });
  const names = ['welcome','email_choose','email_code','google_wait','printer_step','orca_import','import_result','home_signed_out','home_signed_in'];
  const res = [];
  for (const n of names) {
    await page.goto('http://localhost:8765/home.html?scene=' + n);
    await page.waitForTimeout(900);
    await page.evaluate(() => document.querySelectorAll('video').forEach(v => { v.pause(); v.currentTime = 2; }));
    await page.screenshot({ path: `${out}/${n}.png` });
    res.push(n + ': ' + (await page.evaluate(() => document.body.innerText.slice(0, 120).replace(/\n/g,' | '))));
  }
  return res.join('\n');
}

